400	        String trackingNumber = orderShipment.getTrackingNumber();
401	        Long shipmentId = orderShipment.getId();
402	
403	        if (trackingNumber == null || trackingNumber.isBlank()) {
404	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
405	            throw new Xpb98Exception(Xpb98ErrorCode.TRACKING_NUMBER_INVALID);
406	        }
407	
408	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
409	                shipmentId, trackingNumber, orderShipment.getStatus());
410	
411	        Page page = null;
412	        try {
413	
414	            page = browserManager.newPage();
415	            if (page == null) {
416	                throw new Xpb98Exception(Xpb98ErrorCode.BROWSER_INITIALIZATION_ERROR);
417	            }
418	
419	
420	            page.setDefaultTimeout(TIMEOUT_MS);
421	
422	
423	            String url = TRACKING_URL_PREFIX + trackingNumber;
424	            log.debug("배송 조회 페이지로 이동: {}", url);
425	            page.navigate(url);
426	
427	
428	            log.debug("배송 상태 테이블 로드 대기");
429	            page.waitForSelector(STATUS_SELECTOR);
